#include <stdio.h>

typedef enum { DRAFT, MODERATION, PUBLISHED } State;

const char* state_name(State s) {
    switch(s) { case DRAFT: return "Draft"; case MODERATION: return "Moderation"; case PUBLISHED: return "Published"; }
}

State draft_edit() { printf("Editing draft\n"); return DRAFT; }
State draft_review() { printf("Submitting for review\n"); return MODERATION; }
State draft_publish() { printf("Must review first\n"); return DRAFT; }

State mod_edit() { printf("Editing in moderation\n"); return MODERATION; }
State mod_review() { printf("Already in review\n"); return MODERATION; }
State mod_publish() { printf("Publishing\n"); return PUBLISHED; }

State pub_edit() { printf("Unpublishing to edit\n"); return DRAFT; }
State pub_review() { printf("Already published\n"); return PUBLISHED; }
State pub_publish() { printf("Already published\n"); return PUBLISHED; }

State handle(State s, int action) {
    switch(s) {
        case DRAFT: return action==0?draft_edit():action==1?draft_review():draft_publish();
        case MODERATION: return action==0?mod_edit():action==1?mod_review():mod_publish();
        case PUBLISHED: return action==0?pub_edit():action==1?pub_review():pub_publish();
    }
}

int main() {
    State s = DRAFT;
    printf("State: %s\n", state_name(s));
    s = handle(s, 1); printf("State: %s\n", state_name(s));
    s = handle(s, 2); printf("State: %s\n", state_name(s));
    return 0;
}
